import {useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import type {Property} from '../../../../services/rest'
import {defaultValue} from '../Parameters.consts'

import type {filterSearch_parameters$key} from './__generated__/filterSearch_parameters.graphql'

interface BaseProps {
  search: string
  original?: Record<string, string>
}
interface Props extends BaseProps {
  parameters: readonly Property[]
}

export function filterSearch(props: Props) {
  const {parameters, search, original} = props

  if (search.length === 0) {
    return parameters
  }

  return parameters.filter(parameter =>
    [
      parameter.name || defaultValue,
      parameter.value || defaultValue,
      parameter.name != null ? original?.[parameter.name] : undefined,
    ].some(value => value?.toLowerCase().includes(search.toLowerCase())),
  )
}

const fragment = graphql`
  fragment filterSearch_parameters on Properties {
    property {
      name
      value
    }
  }
`
interface HookProps extends BaseProps {
  parametersKey: filterSearch_parameters$key | null
}
export function useFilterSearch({parametersKey, search, original}: HookProps) {
  const {property} = useFragment(fragment, parametersKey) ?? {}
  return useMemo(
    () => filterSearch({parameters: property ?? [], search, original}),
    [property, search, original],
  )
}
