import classNames from 'classnames'
import type {ReactNode} from 'react'
import {memo} from 'react'

import styles from './ParametersPageHeader.module.css'

interface Props {
  className?: string
  children?: ReactNode
}

function ParametersPageHeader(props: Props) {
  const {children} = props

  return <div className={classNames(styles.header, props.className)}>{children}</div>
}

export default memo(ParametersPageHeader)
