import {useAppSelector} from '../../../../hooks/react-redux'
import {GlobalSearchKind} from '../Shortcuts.types'

import {useSearchShortcutEffect} from './useSearchShortcutEffect'
import {useSearchShortcutHandler} from './useSearchShortcutHandler'

export const useSearchShortcutParameters = (callback: () => unknown) => {
  useSearchShortcutEffect({
    kind: GlobalSearchKind.PARAMETERS,
  })

  const enabled = useAppSelector(
    state => state.shortcuts.globalSearch[GlobalSearchKind.PARAMETERS].count > 0,
  )

  useSearchShortcutHandler(enabled, callback)
}
